// /frontend-react/src/components/Dashboard.js

import React from 'react';

const Icon = ({ name, emoji, isActive, onClick, isEasyMode }) => (
    <div 
        onClick={isActive ? onClick : () => isEasyMode && console.log(`Audio: '${name} - Not Available Yet'`)}
        style={{
            padding: '25px', 
            margin: '15px',
            border: `5px solid ${isActive ? '#1A73E8' : '#e0e0e0'}`, 
            borderRadius: '15px', 
            width: '40%',
            textAlign: 'center',
            backgroundColor: isActive ? '#E8F0FE' : '#ffffff', 
            filter: isActive ? 'none' : 'grayscale(80%)', 
            opacity: isActive ? 1 : 0.7, 
            cursor: isActive ? 'pointer' : 'default',
            boxShadow: isActive ? '0 8px 15px rgba(0, 0, 0, 0.3)' : '0 2px 5px rgba(0, 0, 0, 0.1)', 
            transition: 'all 0.3s',
            fontSize: isEasyMode ? '36px' : '20px',
        }}
    >
        <span role="img" aria-label={name} style={{fontSize: isEasyMode ? '85px' : '40px', display: 'block', marginBottom: '10px'}}>{emoji}</span>
        <p style={{fontWeight: 'bold', color: '#333', margin: 0}}>{name}</p>
    </div>
);

function Dashboard({ isEasyMode, goToMedical }) {
    return (
        <div style={{ display: 'flex', flexWrap: 'wrap', justifyContent: 'center', paddingTop: '40px', paddingBottom: '40px' }}>
            <Icon name="Medical Access" emoji="🏥" isActive={true} onClick={goToMedical} isEasyMode={isEasyMode}/>
            <Icon name="Shopping" emoji="🛒" isActive={false} isEasyMode={isEasyMode}/>
            <Icon name="Community" emoji="🧑‍🤝‍🧑" isActive={false} isEasyMode={isEasyMode}/>
            <Icon name="Home Tasks" emoji="🏡" isActive={false} isEasyMode={isEasyMode}/>
        </div>
    );
}

export default Dashboard;
